from hypothesis import strategies as st
from itertools import combinations
from math import comb


@st.composite
def gen(draw):
    n = draw(st.integers(1, 8))
    k = draw(st.integers(1, n))
    # Keep C(n,k) small (always true for n <= 8, but stay explicit).
    if comb(n, k) > 10**6:
        k = 1
    mode = draw(st.sampled_from(["small", "big", "equal", "sorted"]))
    if mode == "small":
        a = draw(st.lists(st.integers(0, 7), min_size=n, max_size=n))
    elif mode == "big":
        a = draw(st.lists(st.integers(0, 2**60 - 1), min_size=n, max_size=n))
    elif mode == "equal":
        v = draw(st.integers(0, 2**60 - 1))
        a = [v] * n
    else:
        a = sorted(draw(st.lists(st.integers(0, 2**60 - 1), min_size=n, max_size=n)))
        if draw(st.booleans()):
            a.reverse()
    return f"{n} {k}\n{' '.join(map(str, a))}\n"


def validate(inp):
    try:
        lines = inp.strip("\n").split("\n")
        if len(lines) != 2:
            return False
        t0 = lines[0].split()
        if len(t0) != 2:
            return False
        n, k = int(t0[0]), int(t0[1])
        t1 = lines[1].split()
        if len(t1) != n:
            return False
        a = [int(x) for x in t1]
    except ValueError:
        return False
    if not (1 <= n <= 2 * 10**5 and 1 <= k <= n):
        return False
    if comb(n, k) > 10**6:
        return False
    if any(x < 0 or x >= 2**60 for x in a):
        return False
    return True


def ref(inp):
    lines = inp.strip("\n").split("\n")
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    best = 0
    for idx in combinations(range(n), k):
        x = 0
        for i in idx:
            x ^= a[i]
        if x > best:
            best = x
    return str(best)
